CREATE TABLE IF NOT EXISTS outreach_openings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, event_year integer NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, leg_id uuid REFERENCES travel_legs(id), quantities jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opening_id uuid NOT NULL REFERENCES outreach_openings(id), opportunity_id uuid NOT NULL REFERENCES booking_opportunities(id), tier text NOT NULL DEFAULT 'unclassified', manual_rank integer NOT NULL DEFAULT 0, decision_due_at timestamptz, meaningful_reply_at timestamptz, convention_ends_on date, released_at timestamptz, checked_at timestamptz, source_snapshot jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES outreach_candidates(id), source_id text NOT NULL, stage text NOT NULL, occurred_at timestamptz NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach_research_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opening_id uuid NOT NULL REFERENCES outreach_openings(id), criteria text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor text NOT NULL, action text NOT NULL, entity_id uuid NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS outreach_candidates_membership_unique ON outreach_candidates(opening_id,opportunity_id);
CREATE UNIQUE INDEX IF NOT EXISTS outreach_candidates_live_opportunity_unique ON outreach_candidates(opportunity_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS outreach_attempts_source_unique ON outreach_attempts(source_id);
CREATE UNIQUE INDEX IF NOT EXISTS outreach_attempts_stage_unique ON outreach_attempts(candidate_id,stage);
CREATE UNIQUE INDEX IF NOT EXISTS outreach_research_criteria_unique ON outreach_research_tasks(opening_id,criteria);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'outreach_openings'::regclass AND conname = 'outreach_openings_window_valid') THEN ALTER TABLE outreach_openings ADD CONSTRAINT outreach_openings_window_valid CHECK (ends_on >= starts_on AND extract(year from starts_on) = event_year AND extract(year from ends_on) = event_year AND event_year between 2000 and 2200); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'outreach_openings'::regclass AND conname = 'outreach_openings_quantities_valid') THEN ALTER TABLE outreach_openings ADD CONSTRAINT outreach_openings_quantities_valid CHECK (jsonb_typeof(quantities) = 'object'); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'outreach_candidates'::regclass AND conname = 'outreach_candidates_rank_valid') THEN ALTER TABLE outreach_candidates ADD CONSTRAINT outreach_candidates_rank_valid CHECK (manual_rank >= 0); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'outreach_candidates'::regclass AND conname = 'outreach_candidates_tier_valid') THEN ALTER TABLE outreach_candidates ADD CONSTRAINT outreach_candidates_tier_valid CHECK (tier in ('dedicated','convention','strong','filler','unclassified')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'outreach_attempts'::regclass AND conname = 'outreach_attempts_stage_valid') THEN ALTER TABLE outreach_attempts ADD CONSTRAINT outreach_attempts_stage_valid CHECK (stage in ('initial','follow_up_1','follow_up_2')); END IF; END $$;

ALTER TABLE outreach_openings ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'open';
ALTER TABLE outreach_candidates ADD COLUMN IF NOT EXISTS history_review jsonb;
ALTER TABLE outreach_research_tasks ADD COLUMN IF NOT EXISTS results jsonb;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='outreach_openings'::regclass AND conname='outreach_openings_status_valid') THEN ALTER TABLE outreach_openings ADD CONSTRAINT outreach_openings_status_valid CHECK (status in ('open','filled','closed')); END IF; END $$;
